<?php use App\Core\View;ob_start(); ?><h1>Escolha seu plano</h1><div class="grid"><?php foreach($plans as $p):?><article><h2><?=View::e($p['name'])?></h2><strong>R$ <?=number_format($p['amount_cents']/100,2,',','.')?><?=$p['is_recurring']?'/mês':''?></strong><form method="post" action="/checkout"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="plan" value="<?=View::e($p['code'])?>"><label>Pagamento<select name="method"><option value="credit_card">Cartão de crédito</option><option value="pix">PIX</option><option value="boleto">Boleto</option></select></label><button class="btn">Ir para pagamento</button></form></article><?php endforeach?></div><?php $body=ob_get_clean();$title='Planos';require __DIR__.'/layout.php'; ?>
